quests[7810] = { title = "Arena Master", description = "There must be more to being a master of the arena than this!   Perhaps the Pirate who runs the event at Gurubashi will know!", objectives = "Speak with Short John Mithril in the Stranglethorn Arena.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
