quests[7886] = { title = "Talismans of Merit", description = "You have proven your value to our efforts in Warsong Gulch. Continue to aid the cause and bring me more talismans of merit. Do this, and you will earn even more of our trust.", objectives = "You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
