quests[7937] = { title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you in Eastvale.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Eastvale Logging Camp in Elwynn Forest.  Focusing closer in on the image, you see a haystack that sits next to a stable.", objectives = "Travel to the Eastvale Logging Camp in Elwynn Forest and seek out your fortune.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7938] = { title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you inside the Deadmines.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Deadmines inside Westfall's ruined hamlet of Moonbrook.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the mines itself.  Stepping through it, a strange chest appears out from nowhere.", objectives = "Travel to the Deadmines in Westfall and seek out your fortune.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
