quests[7944] = { title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you inside Wailing Caverns.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of a cave to the southwest of the Crossroads in the Barrens.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the caverns itself.  Stepping through it, a strange chest appears out from nowhere.", objectives = "Travel to the Wailing Caverns in the Barrens and seek out your fortune.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
quests[7945] = { title = "Your Fortune Awaits You...", description = "\"Your fortune awaits you outside Palemane Rock.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Palemane Rock of Mulgore.  Focusing closer in on the image, you see a tree stump that sits close to the cave entrance.", objectives = "Travel to Palemane Rock in Mulgore and seek out your fortune.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "enUS" }
